# RTR loader for hunt_persistence.ps1 v2.0 -- gzip+base64 compressed
# Usage: powershell -File hunt_persistence_loader.ps1 [args]
# Example: powershell -File hunt_persistence_loader.ps1 -Deep -MinSeverity High

$Payload = ''
$gz = New-Object IO.Compression.GZipStream((New-Object IO.MemoryStream(, [Convert]::FromBase64String($Payload))), [IO.Compression.CompressionMode]::Decompress)
$code = (New-Object IO.StreamReader($gz)).ReadToEnd()
$gz.Dispose()
& ([scriptblock]::Create($code)) @args